/* Each word sits in an inline-block mask that crops it (overflow: clip is not a scroll
   container, so the view timeline still works). The padding plus an equal negative margin
   leaves room for ascenders and descenders without changing the line height. Each letter
   starts --d below its place: the first barely, later ones further, so a line reads as a
   wave settling from left to right. */
.lunchline-letter-rise-mask {
  display: inline-block;
  overflow: clip;
  vertical-align: top;
  padding-block: 0.1em 0.2em;
  margin-block: -0.1em -0.2em;
}

.lunchline-letter-rise-ch {
  display: inline-block;
}

/* scroll mode: the heading itself is the timeline, so all its letters share it */
.lunchline-letter-rise[data-mode="scroll"] {
  view-timeline-name: --lunchline-letter-rise;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .lunchline-letter-rise[data-mode="scroll"] .lunchline-letter-rise-ch {
      animation: lunchline-letter-rise-up linear both;
      animation-timeline: --lunchline-letter-rise;
      animation-range: entry 0% cover 45%;
    }
  }
}

/* load mode: once, on the original's ease-out cubic, 22ms apart */
@media (prefers-reduced-motion: no-preference) {
  .lunchline-letter-rise[data-mode="load"] {
    animation: lunchline-letter-rise-fade 0.6s cubic-bezier(0.215, 0.61, 0.355, 1) both;
    animation-delay: var(--lunchline-letter-rise-delay, 0ms);
  }
  .lunchline-letter-rise[data-mode="load"] .lunchline-letter-rise-ch {
    animation: lunchline-letter-rise-up 1s cubic-bezier(0.215, 0.61, 0.355, 1) both;
    animation-delay: calc(var(--lunchline-letter-rise-delay, 0ms) + var(--i, 0) * 22ms);
  }
}

@keyframes lunchline-letter-rise-up {
  from {
    transform: translateY(var(--d, 0.5em));
  }
  to {
    transform: none;
  }
}

@keyframes lunchline-letter-rise-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

import { Fragment, type CSSProperties, type ElementType } from "react";
import { cn } from "@foundry/foundry-utils";
import "./lunchline-letter-rise.css";

export interface LunchlineLetterRiseProps {
  /** the text; split into words (each its own mask) and letters */
  text: string;
  /** the element to render: h2 by default */
  as?: ElementType;
  /** "scroll": the letters rise as the heading scrolls into view, scrubbed with the scroll;
      "load": they rise once when the page loads (for the first screen) */
  mode?: "scroll" | "load";
  /** load mode only: wait this long (ms) before the first letter moves */
  delay?: number;
  /** how far the first letter starts below its place, in em; each next letter starts 15%
      further down, up to `maxDrop` */
  drop?: number;
  /** the furthest any letter starts below its place, in em (about one line hides it fully) */
  maxDrop?: number;
  /** size, leading, weight and colour go here */
  className?: string;
}

export function LunchlineLetterRise({
  text,
  as: Tag = "h2",
  mode = "scroll",
  delay = 0,
  drop = 0.11,
  maxDrop = 1.05,
  className,
}: LunchlineLetterRiseProps) {
  const words = text.split(/\s+/).filter(Boolean);
  let index = 0;
  return (
    <Tag
      aria-label={text}
      data-mode={mode}
      className={cn("lunchline-letter-rise", className)}
      style={{ "--lunchline-letter-rise-delay": `${delay}ms` } as CSSProperties}
    >
      {words.map((word, w) => (
        <Fragment key={w}>
          <span aria-hidden className="lunchline-letter-rise-mask">
            {Array.from(word).map((letter, l) => {
              const i = index++;
              const d = Math.min(drop * Math.pow(1.15, i), maxDrop);
              return (
                <span key={l} className="lunchline-letter-rise-ch" style={{ "--i": i, "--d": `${d.toFixed(3)}em` } as CSSProperties}>
                  {letter}
                </span>
              );
            })}
          </span>
          {w < words.length - 1 && " "}
        </Fragment>
      ))}
    </Tag>
  );
}
